+static const int INITIAL_TABLE_SIZE = 15889;
+using ClassesTable = HashTable<Klass*, bool, INITIAL_TABLE_SIZE, AnyObj::C_HEAP, mtClassShared>;
+ClassesTable* _classes_added = nullptr;
