+class AotSafeLoaderClassRecipeMap: public ResizeableHashTable<Symbol*, ClassRecipeList*, AnyObj::C_HEAP, mtClass>
+{
+  using ResizeableHashTableBase = ResizeableHashTable<Symbol*, ClassRecipeList*, AnyObj::C_HEAP, mtClass>;
+private:
