+  } else {
+    parent_cl_data = java_lang_ClassLoader::loader_data(parent);
+  }
+  Dictionary* parent_dict = parent_cl_data->dictionary();
+  KlassCollector collector;
+  parent_dict->all_entries_do(&collector);
